def canMakeRow(cards):
    # Check if the row is already in the correct order
    if not all(card in 'abc' for card in cards):
        return "NO"

    # Check if we can swap two cards
    for i in range(len(cards)):
        for j in range(i+1, len(cards)):
            if cards[i] == cards[j]:
                return "NO"

    # If we can swap, return "YES"
    return "YES"

def maxProduct(n, a):
