    for i in range(n):
        if a[i] == 1:
            max_product += 1
    return max_product

def remove_black_cells(n, k):
    operations = []
    for i in range(n):
        if i % k == 0:
            operations.append('WW')
        else:
            operations.append('B')
    return operations

