        arr[i] = 0
        for j in range(len(logs)):
            if logs[j][0] <= queries[i] <= logs[j][1]:
                arr[i] += 1
    return arr

def minOperations(num1, num2):
    if num1 == 0:
        return 0
    elif num2 == 0:
        return -1
    else:
        i = 0
        while num1 > 0:
            num1 -= 2**i + num2
            i += 1
        return i

