def countCompleteSubstrings(word, k):
    # Initialize a dictionary to store the count of each complete substring
    count = {}

    # Iterate over the word
    for i in range(len(word)):
        # Initialize a counter for each complete substring
        for j in range(i, len(word)):
            # If the difference between the characters at the current position and the previous position is at most 2
            if abs(word[i] - word[j]) <= 2:
                # If the current character is not in the dictionary
                if word[i] not in count:
                    # Add the current substring to the dictionary
                    count[word[i]] = 1
                # If the current character is in the dictionary
                else:
                    # Increment the count of the current substring
                    count[word[i]] += 1

    # Return the count of complete substrings
    return sum(count.values())

