    for i in range(len(nums)):
        freq[nums[i]] = 0

    # Iterate through the array
    for i in range(len(nums)):
        # If the frequency of the current element is less than or equal to k
        if freq[nums[i]] <= k:
            # If the length of the current subarray is greater than the current length of the longest good subarray
            if max_length < len(nums[i]):
                max_length = len(nums[i])

            # Update the frequency of the current element
            freq[nums[i]] += 1

    return max_length

