def longestSpecialSubstring(s):
    # Initialize a dictionary to store the length of each substring
    length_dict = {}

    # Initialize a counter to keep track of the length of each substring
    length_counter = 0

    # Iterate over the string s
    for i in range(len(s)):
        # If the current character is a special character, increment the length counter
        if s[i] in 'abcdef':
            length_counter += 1

        # If the length counter is greater than 3, update the length of the longest substring
        if length_counter > 3:
            max_length = max(length_counter, length_dict.get(length_counter, 0))
            length_dict[length_counter] = max_length
            length_counter = 0

    # If the length counter is still greater than 3, return -1
    if length_counter > 3:
        return -1

    # If the length counter is 0, return the length of the longest substring
    if length_counter == 0:
        return length_dict.get(length_counter, 0)

    # If the length counter is 1, return the length of the longest substring
    return length_dict.get(length_counter, 0)

