def maxConsecutive(nums):
    max_consecutive = 0
    for i in range(len(nums)):
        if i == 0 or nums[i] > nums[i-1]:
            max_consecutive = max(max_consecutive, i-1)
        elif i == len(nums)-1 or nums[i] > nums[i+1]:
            max_consecutive = max(max_consecutive, i+1)
    return max_consecutive

def remove_underlined_chars(s):
    # Initialize the result string
    result = ""
    # Iterate over each character in the string
    for char in s:
        # If the character is an underlined character, remove it
        if char.isalpha():
            # If the character is an underlined character, remove it
            if char == 'a':
                result += 'b'
            elif char == 'b':
                result += 'c'
            elif char == 'c':
                result += 'd'
            else:
                result += char
        else:
            # If the character is not an underlined character, add it to the result
            result += char
    return result

