def maxPalindromes(words):
    n = len(words)
    max_palindromes = 0

    for i in range(n):
        for j in range(i+1, n):
            x = words[i][0]
            y = words[j][0]

            if i == j:
                continue

            if x == y:
                continue

            if words[i][x] != words[j][y]:
                continue

            if words[i][x] == words[j][y]:
                max_palindromes += 1

    return max_palindromes

