def longestCommonPrefix(arr1, arr2):
    # Initialize the longest common prefix length
    max_length = 0

    # Initialize a dictionary to store the common prefix lengths
    common_prefix_dict = {}

    # Iterate over all pairs (x, y)
    for x in arr1:
        for y in arr2:
            # Check if x and y are in the same array
            if x == y:
                # If they are, add the length of the common prefix to the max_length
                if x in common_prefix_dict:
                    max_length = max(max_length, common_prefix_dict[x])
                else:
                    common_prefix_dict[x] = max_length
            else:
                # If they are not in the same array, add the length of the common prefix to the max_length
                if y in common_prefix_dict:
                    max_length = max(max_length, common_prefix_dict[y])
                else:
                    common_prefix_dict[y] = max_length

    # Return the length of the longest common prefix
    return max_length

def distribute(nums):
    arr1 = [nums[0]]
    arr2 = [nums[1]]
    for i in range(2, len(nums)):
        if nums[i] > nums[i-1]:
            arr1.append(nums[i])
        else:
            arr2.append(nums[i])
    result = arr1 + arr2
    return result

def overall_winner(S):
    # Initialize variables
    wins_Takahashi = 0
    wins_Aoki = 0

    # Iterate through the string S
    for i in range(len(S)):
        # If the i-th character is T, it means Takahashi won
        if S[i] == 'T':
            wins_Takahashi += 1
        # If the i-th character is A, it means Aoki won
        elif S[i] == 'A':
            wins_Aoki += 1
        # If the i-th character is not T or A, it means it's a tie
        else:
            wins_Takahashi += wins_Aoki
            wins_Aoki = 0

    # If the overall winner is Takahashi, print T
    if wins_Takahashi > wins_Aoki:
        print('T')
    # If the overall winner is Aoki, print A
    else:
        print('A')

def is_cheating_allowed(S, T):
    # Check if S and T are valid strings
    if not all(c.isalpha() or c == '@' for c in S) or not all(c.isalpha() or c == '@' for c in T):
        return False

    # Check if the two rows are the same
    if len(S) != len(T):
        return False

    # Check if the two rows can be rearranged freely
    for i in range(len(S)):
        for j in range(len(T)):
            if S[i] == T[j]:
                S[i], T[j] = T[j], S[i]
                if S == T:
                    return True
    return False

