    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == s:
                cells.append((i, j))

    # Initialize the set of cells
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == n:
                cells.append((i, j))

    # Initialize the set of cells
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == u:
                cells.append((i, j))

    # Initialize the set of cells
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == k:
                cells.append((i, j))

    # Initialize the set of cells
    for i in range(len(grid)):
        for j in range(len(grid[0])):
