def generate_stars(N):
    # Initialize the stars
    stars = []
    for i in range(N):
        stars.append(i)

    # Initialize the levels
    levels = [0] * (N + 1)

    # Initialize the tree
    tree = [0] * (N + 1)

    # Initialize the levels of the tree
    for i in range(N + 1):
        tree[i] = i

    # Initialize the levels of the stars
    for i in range(N + 1):
        levels[i] = i

    # Generate the stars
    for i in range(N + 1):
        for j in range(i + 1, N + 1):
            if tree[j] == i:
                levels[j] = levels[i]
                break

    # Sort the levels in ascending order
    levels.sort()

    # Print the levels
    for i in range(N + 1):
        print(levels[i], end=" ")

    # Print the stars
    for i in range(N + 1):
        print(stars[i], end=" ")

def approximate_number(N):
    if N <= 10**3 - 1:
        return N
    elif 10**3 <= N <= 10**4 - 1:
        return str(int(N) // 10) + '0'
    elif 10**4 <= N <= 10**5 - 1:
        return str(int(N) // 100) + '0'
    elif 10**5 <= N <= 10**6 - 1:
        return str(int(N) // 1000) + '0'
    elif 10**6 <= N <= 10**7 - 1:
        return str(int(N) // 10000) + '0'
    elif 10**7 <= N <= 10**8 - 1:
        return str(int(N) // 100000) + '0'
    elif 10**8 <= N <= 10**9 - 1:
        return str(int(N) // 1000000) + '0'
    else:
        return str(int(N) // 10000000) + '0'

