def find_321_like_number(n):
    # Generate all 321-like numbers
    numbers = [i for i in range(1, n+1) if (i % 3 == 0 and i % 5 == 0) or (i % 7 == 0 and i % 11 == 0)]

    # Find the K-th smallest number
    for i in range(1, n+1):
        if i % 3 == 0 and i % 5 == 0:
            if i == 1:
                continue
            if numbers[i-1] < numbers[i]:
                numbers[i] = numbers[i-1]
                numbers[i-1] = i

    return numbers[n-1]

