def find_good_integer(n):
    # Check if n is a good integer
    if n < 0 or n % 2 != 0:
        return "Error: Input must be a positive integer."

    # Convert n to decimal
    decimal_n = int(str(n)[::-1])

    # Check if all digits in decimal n are even numbers
    for i in range(1, len(str(decimal_n))):
        if decimal_n % 2 != 0:
            return "Error: All digits in decimal n must be even numbers."

    # Find the N-th smallest good integer
    for i in range(1, n + 1):
        if i % 2 == 0:
            if i > decimal_n:
                return "Error: The N-th smallest good integer is greater than the decimal n."
            else:
                return i
    return "Error: The N-th smallest good integer is not found."

def max_size_pyramid_sequence(A):
    # Initialize the size of the pyramid sequence
    size = 1

    # Iterate over the sequence A
    for i in range(len(A)):
        # Choose one term of the sequence and decrease its value by 1
        if i == 0:
            size += 1
        elif i == len(A) - 1:
            size -= 1
        else:
            size += 1

        # Remove the first or last term
        if i == 0:
            size -= 1
        elif i == len(A) - 1:
            size -= 1
        else:
            size -= 1

        # Check if the size of the pyramid sequence is greater than the current size
        if size > size:
            size = size + 1

    return size

