def solve(H, W, K):
    # Initialize variables
    operations = 0

    # Check if it is possible to satisfy the condition
    if not (H * W <= 2 * 10**5 and 1 <= H and 1 <= W and H * W <= 2 * 10**5 and 1 <= K and K <= H * W):
        return -1

    # Initialize a list to store the operations
    operations_list = []

    # Iterate through all possible pairs (i, j)
    for i in range(H):
        for j in range(W - K + 1):
            # Check if the characters in cells (i, j), (i, j+1), \ldots, (i, j+K-1) are all o
            if all(cell[i] == 'o' for cell in operations_list):
                operations += 1
                operations_list.append((i, j))

    # Check if it is possible to satisfy the condition
    if not operations_list:
        return -1

    # Find the minimum number of operations required
    return min(operations_list)

