def max_palindromic_cube(N):
    # Check if N is a palindromic cube number
    if N == N[::-1]:
        return N

    # Check if N is a palindromic cube number
    for i in range(1, N):
        if N % i == 0:
            return N

    # If N is not a palindromic cube number, return the maximum value of N
    return max(N, N // N)

