def check_consecutive_appearances(A, B):
    # Check if A and B are distinct
    if len(set(A)) != len(A):
        return False

    # Check if A and B are pairwise distinct
    if len(set(A)) != len(set(B)):
        return False

    # Check if A and B are sorted in ascending order
    if sorted(A) != sorted(B):
        return False

    # Check if C contains two consecutive elements appearing in A
    for i in range(len(A)):
        for j in range(i + 1, len(A)):
            if A[i] == A[j]:
                return True

    return False
