def hasSubstring(s, substring):
    if len(substring) != 2:
        return False

    reverse_s = s[::-1]
    for i in range(len(reverse_s)):
        if reverse_s[i] == substring[0]:
            if i == 0:
                return True
            elif i == 1:
                return True
            else:
                return False
    return False

