def remove_point(points):
    # Initialize the maximum distance to 0
    max_distance = 0

    # Iterate through the points
    for i in range(len(points)):
        # Calculate the Manhattan distance between the current point and the previous point
        distance = abs(points[i][0] - points[i-1][0]) + abs(points[i][1] - points[i-1][1])

        # Update the maximum distance if the current point is removed
        if i == 0:
            max_distance = max(max_distance, distance)
        else:
            max_distance = max(max_distance, distance)

    return max_distance

def maxDistanceBetweenPrimeNumbers(nums):
    prime_nums = [num for num in nums if all(num % i != 0 for i in range(2, int(num**0.5) + 1))]
    return max(abs(num - prime_nums[0]) for num in prime_nums)

def encrypt(nums):
    encrypted_nums = []
    for num in nums:
        encrypted_nums.append(max(num, key=num))
    return sum(encrypted_nums)

def powerOfSubsequence(nums, k):
    if k == 0:
        return 0

    power = 0
    for i in range(len(nums)):
        if i == 0:
            power += 1
        else:
            power += nums[i] * powerOfSubsequence(nums, k - 1)

    return power

