def min_nums(n, x):
    nums = [x]
    for i in range(n - 1):
        nums.append(nums[-1] & nums[i + 1])
    return min(nums)

def median(nums):
    # Sort the array
    nums.sort()

    # Get the median
    n = len(nums)
    if n % 2 == 0:
        return (nums[n // 2] + nums[n // 2 - 1]) / 2
    else:
        return nums[n // 2]

def is_valid_word(word):
    # Check if the word is valid
    if len(word) < 3 or not all(char.isalpha() for char in word):
        return False

    # Check if the word contains at least one vowel
    vowels = set('aeiouAEIOU')
    if not any(char in vowels for char in word):
        return False

    # Check if the word contains at least one consonant
    consonants = set('bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ')
    if not any(char in consonants for char in word):
        return False

    return True

