def generate_stable_binary_arrays(zero, one, limit):
    # Initialize an empty list to store the stable binary arrays
    stable_binary_arrays = []

    # Iterate over all possible values of zero
    for i in range(zero, one + 1):
        # Iterate over all possible values of one
        for j in range(one, limit + 1):
