    return len(stable_binary_arrays)

def digit_diff(nums):
    total_diff = 0
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            diff = nums[i] - nums[j]
            total_diff += diff
    return total_diff

def generate_ways(k):
    ways = []
    for i in range(1, k+1):
        if i == 0:
            ways.append(1)
        else:
            ways.append(ways[i-1] + ways[i-1] + ways[i-1] + ways[i-1])
    return ways

def countGoodPairs(nums1, nums2, k):
    n = len(nums1)
    m = len(nums2)
    good_pairs = 0

    for i in range(n):
        for j in range(m):
            if nums1[i] % nums2[j] * k == 0:
                good_pairs += 1

    return good_pairs

def compress_word(word):
